"""Actual relay/custody/privacy integration; explicit fixtures, never natural outcome claims."""
import argparse,json,unittest
from pathlib import Path
from test_unified_integration import UnifiedIntegration
from test_continuity import RecordedResult
class KnowledgeIntegration(UnifiedIntegration):
    def field(self,p):
        self.configure(p,"""s.remoteCore.autonomyEnabled=false;s.frontier.enabled=false;s.remoteCore.missions.derelict=null;s.equipment.B07.condition=80;s.power=100;s.remoteCore.asteroid.relays=0;
        const q=s.crew[0];q.expeditionAway='asteroid';q.expeditionId='KNOWLEDGE-FIXTURE';q.route=[];q.energy=85;q.vitals.health=100;q.vitals.morale=70;
        s.remoteCore.missions.asteroid={id:'KNOWLEDGE-FIXTURE',crew:q.name,members:[q.name],phase:'onsite',progress:0,kit:1,suits:0,cargo:{food:2,water:4,oxygen:4},conditions:{},onsiteMinutes:0};s.economy.initial.food+=2;s.economy.initial.water+=4;s.economy.initial.oxygen+=4;s.asteroidExploration.position=23;s.asteroidExploration.fieldRelays=[];s.asteroidExploration.step=0;""")
    def change(self,p,code):
        p.evaluate('__icarusSoak.save()');key='knowledge-change-'+str(getattr(self,'changes',0));self.changes=getattr(self,'changes',0)+1;script=self.codec+";(()=>{if(sessionStorage.getItem('"+key+"'))return;sessionStorage.setItem('"+key+"','1');const raw=localStorage.getItem('icarus-anthology-v14');const s=JSON.parse(raw.startsWith('ICARUS-LZ1:')?LZString.decompressFromUTF16(raw.slice(11)):raw);"+code+";localStorage.setItem('icarus-anthology-v14',JSON.stringify(s));})();";p.add_init_script(script);p.reload();p.wait_for_function('!!window.__icarusSoak')
    def observe(self,p):
        return p.evaluate("()=>__icarusSoak.knowledgeAction('event',{text:'Unverified military field finding',people:['Frank Morrow'],data:{uncertain:true}})")
    def test_isolated_observer_pending_report_and_private_recap(self):
        p=self.page();self.field(p);r=self.observe(p);p.evaluate("__icarusSoak.knowledgeAction('tick',{})");s=self.snap(p);f=next(f for f in s['knowledge']['facts'].values() if f['sourceId']==r['id']);self.assertIn(f['id'],s['knowledge']['actors']['Frank Morrow']['entries']);self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.assertFalse(any('Unverified military field finding' in e['message'] for e in s['events']));self.assertFalse(any(r['id'] in w['sourceIds'] for w in s['chronicles']['weeks'].values()));self.assertEqual(f['confidence'],.45)
    def test_actual_relay_chain_restoration_delivers_once_and_survives_reload(self):
        p=self.page();self.field(p);r=self.observe(p);p.evaluate("__icarusSoak.knowledgeAction('tick',{})");before=self.snap(p);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),before)
        self.change(p,"s.asteroidExploration.fieldRelays=[1,2,3,4].map(zone=>({zone,room:zone*5,battery:100,integrity:100,boosted:false}));");self.advance(p,1);s=self.snap(p);f=next(f for f in s['knowledge']['facts'].values() if f['sourceId']==r['id']);self.assertIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.assertTrue(f.get('publicationSourceId'));self.assertEqual(sum(e.get('data',{}).get('sourceFactId')==f['id'] for e in s['chronicle']['records']),1);self.advance(p,2);self.assertEqual(sum(e.get('data',{}).get('sourceFactId')==f['id'] for e in self.snap(p)['chronicle']['records']),1)
    def test_sender_death_before_restored_radio_does_not_deliver_or_repopulate(self):
        p=self.page();self.field(p);r=self.observe(p);p.evaluate("__icarusSoak.knowledgeAction('tick',{})");self.change(p,"s.crew[0].vitals.health=0;s.asteroidExploration.fieldRelays=[1,2,3,4].map(zone=>({zone,room:zone*5,battery:100,integrity:100}));");self.advance(p,1);s=self.snap(p);f=next(f for f in s['knowledge']['facts'].values() if f['sourceId']==r['id']);self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries']);self.assertEqual(len(s['crew']),19);self.assertTrue(any(x['name']=='Frank Morrow' for x in s['living']['deceased']));self.assertIn(f['id'],s['knowledge']['actors']['Frank Morrow']['entries'])
    def test_broken_ship_receiver_blocks_good_field_relays(self):
        p=self.page();self.field(p);r=self.observe(p);self.change(p,"s.equipment.B07.condition=0;s.asteroidExploration.fieldRelays=[1,2,3,4].map(zone=>({zone,room:zone*5,battery:100,integrity:100}));");p.evaluate("__icarusSoak.knowledgeAction('tick',{})");s=self.snap(p);f=next(f for f in s['knowledge']['facts'].values() if f['sourceId']==r['id']);self.assertNotIn(f['id'],s['knowledge']['actors']['SOL']['entries'])
    def test_military_archive_is_not_shared_until_report_received(self):
        p=self.page();self.field(p);self.change(p,"s.asteroidExploration.rooms.forEach(r=>{r.visited=true;r.object=null;});s.asteroidExploration.rooms[23].visited=false;s.asteroidExploration.position=22;s.asteroidExploration.step=13;");self.advance(p,1);s=self.snap(p);self.assertTrue(any(a['id']=='WRECK-CELL-23' for a in s['unifiedWorld']['archives']));self.deck(p,'research','evidence');p.locator('summary').filter(has_text='IN-GAME ARCHIVES').click();self.assertNotIn('Wreck Command',p.locator('#acquired-lore').inner_text());self.assertNotIn('PRIVATE CANON',p.locator('#actor-knowledge').inner_text())
    def test_legacy_save_without_ledger_migrates_once_without_changing_existing_world(self):
        p=self.page();self.advance(p,60);self.change(p,"delete s.knowledge;");s=self.snap(p);self.assertEqual(s['knowledge']['version'],1);self.assertEqual(len(s['crew']),20);p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),s)
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--report',default='knowledge_integration.json');args=ap.parse_args();r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.defaultTestLoader.loadTestsFromTestCase(KnowledgeIntegration));Path(args.report).write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[{'test':str(t),'detail':d} for t,d in r.failures],'errors':[{'test':str(t),'detail':d} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
